-- Robotics/Embedded/IoT pathway ("Vector Division") Act 14 -- "Connected
-- Things" content, under world-vec-connected-things (already inserted by
-- the Acts 11-15 spine migration, 20260813180000). 1 campaign, 2
-- operations, 12 missions (11 lessons + boss), following the same
-- campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other Act. No new ChallengeType
-- needed -- reuses story_dialogue, multiple_choice, drag_and_drop,
-- investigation, interactive_diagram, browser_simulation (generic
-- console fallback) and boss_encounter.
--
-- Opens Arc III ("Connect the Physical World"). Byte's facility-wide
-- sweep finishes counting: 10,417 embedded controllers match the door's
-- signature, and only 82 of them have any reachable network path at all.
-- Deliberate restraint, same as every prior reveal in this pathway: this
-- is NOT a spreading attack or a coordinated SUBSTRATE action. The count
-- is evidence of history, not intrusion -- almost all of these devices
-- were installed once, decades ago, with no device identity and no
-- connectivity plan of any kind, and simply left running. No substrate
-- dialogue lines this Act (the pathway is deliberately pacing those
-- further apart); diagnostic-format flavor text in evidence is fine, it
-- is just never attributed to the substrate character_id. The boss
-- mission designs the actual identity + provisioning + connectivity plan
-- for the newly discovered population and closes on the pivot into Act
-- 15: identity and a radio are not the same as a working pipeline.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-connected-things', 'world-vec-connected-things', 'connected-things', '14A - Connected Things', 'Learn the vocabulary of connecting a physical device to everything else -- IoT architecture, device identity, provisioning, Wi-Fi, Bluetooth Low Energy, BLE services and characteristics, MQTT, topics and QoS, HTTP and CoAP on constrained devices, and the trade-offs between them -- while Vector Division designs a real identity and connectivity plan for the ten thousand controllers Byte''s sweep just found.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-connected-things-1', 'campaign-vec-connected-things', 'the-real-number', 'The Real Number', 'IoT architecture, device identity, provisioning, Wi-Fi concepts, Bluetooth/BLE concepts and BLE services and characteristics.', 1),
  ('operation-vec-connected-things-2', 'campaign-vec-connected-things', 'a-plan-for-ten-thousand', 'A Plan for Ten Thousand', 'MQTT, topics and QoS, HTTP on devices, CoAP concepts, connectivity trade-offs, and designing the actual plan.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-connected-things-01', 'world-vec-connected-things', 'campaign-vec-connected-things', 'operation-vec-connected-things-1', 'iot-architecture', 'IoT Architecture: Edge, Gateway, Cloud', 'Byte''s facility-wide sweep, promised at the end of Arc II, finishes counting -- and the number of embedded controllers matching the door''s signature is far higher than anyone expected, almost all of them with no way to reach or be reached by anything at all.', 'beginner', ARRAY['imani','byte','tomas'], null, null, '{"type":"simulation","simulationId":"iot-architecture-sim"}'::jsonb, '{"xp":210,"credits":25}'::jsonb, false, 1),
  ('mission-vec-connected-things-02', 'world-vec-connected-things', 'campaign-vec-connected-things', 'operation-vec-connected-things-1', 'device-identity', 'Device Identity', 'Most of the newly counted controllers share nothing but a factory model number. Tomas starts with what a device actually needs before it can be trusted: a real identity of its own.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-connected-things-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"device-identity-sim"}'::jsonb, '{"xp":210,"credits":30}'::jsonb, false, 2),
  ('mission-vec-connected-things-03', 'world-vec-connected-things', 'campaign-vec-connected-things', 'operation-vec-connected-things-1', 'provisioning', 'Provisioning', 'A working identity means nothing without a process that actually installs it. Tomas walks through what provisioning is supposed to look like -- and how completely the newly found controllers skipped every step of it.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-connected-things-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"provisioning-sim"}'::jsonb, '{"xp":220,"credits":30}'::jsonb, false, 3),
  ('mission-vec-connected-things-04', 'world-vec-connected-things', 'campaign-vec-connected-things', 'operation-vec-connected-things-1', 'wifi-concepts', 'Wi-Fi Concepts', 'Hundreds of the newly counted boards already carry a Wi-Fi radio, unused. Before deciding whether that radio is useful here, the player has to understand what Wi-Fi actually costs a small, power-limited device.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-connected-things-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"wifi-concepts-sim"}'::jsonb, '{"xp":220,"credits":30}'::jsonb, false, 4),
  ('mission-vec-connected-things-05', 'world-vec-connected-things', 'campaign-vec-connected-things', 'operation-vec-connected-things-1', 'bluetooth-ble-concepts', 'Bluetooth and BLE Concepts', 'Not every controller can afford Wi-Fi''s power draw. Bluetooth Low Energy exists for exactly that gap -- short range, low power, and a very different way of talking to the world.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-connected-things-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"bluetooth-ble-concepts-sim"}'::jsonb, '{"xp":230,"credits":35}'::jsonb, false, 5),
  ('mission-vec-connected-things-06', 'world-vec-connected-things', 'campaign-vec-connected-things', 'operation-vec-connected-things-1', 'ble-services-characteristics', 'BLE Services and Characteristics', 'A BLE radio alone does not describe what a device can say. Services and characteristics do -- the actual vocabulary a BLE device uses to expose whatever it measures.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-connected-things-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"ble-services-characteristics-sim"}'::jsonb, '{"xp":230,"credits":35}'::jsonb, false, 6),
  ('mission-vec-connected-things-07', 'world-vec-connected-things', 'campaign-vec-connected-things', 'operation-vec-connected-things-2', 'mqtt', 'MQTT: Publish and Subscribe', 'A protocol built for exactly this problem: thousands of small devices, unreliable links, and a need to report in without carrying the weight of a full web server on either end.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-connected-things-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"mqtt-sim"}'::jsonb, '{"xp":240,"credits":35}'::jsonb, false, 7),
  ('mission-vec-connected-things-08', 'world-vec-connected-things', 'campaign-vec-connected-things', 'operation-vec-connected-things-2', 'topics-and-qos', 'Topics and Quality of Service', 'MQTT''s simplicity hides two decisions that decide whether ten thousand devices reporting at once is manageable or chaos: how their topics are organized, and how strongly each message insists on arriving.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-connected-things-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"topics-and-qos-sim"}'::jsonb, '{"xp":240,"credits":40}'::jsonb, false, 8),
  ('mission-vec-connected-things-09', 'world-vec-connected-things', 'campaign-vec-connected-things', 'operation-vec-connected-things-2', 'http-on-devices', 'HTTP on Devices', 'The obvious choice is not always the right one. HTTP works fine on a constrained device -- Tomas wants the player to actually price out what that convenience costs in power and bandwidth first.', 'beginner', ARRAY['byte','tomas'], '{"requiredMissionIds":["mission-vec-connected-things-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"http-on-devices-sim"}'::jsonb, '{"xp":250,"credits":40}'::jsonb, false, 9),
  ('mission-vec-connected-things-10', 'world-vec-connected-things', 'campaign-vec-connected-things', 'operation-vec-connected-things-2', 'coap-concepts', 'CoAP Concepts', 'A protocol built to look like HTTP without costing what HTTP costs -- CoAP trades away a few rarely-needed features for a footprint small enough for the tightest power budget on the list.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-connected-things-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"coap-concepts-sim"}'::jsonb, '{"xp":250,"credits":40}'::jsonb, false, 10),
  ('mission-vec-connected-things-11', 'world-vec-connected-things', 'campaign-vec-connected-things', 'operation-vec-connected-things-2', 'connectivity-tradeoffs', 'Connectivity Trade-Offs', 'No single answer covers ten thousand different devices. Tomas asks the player to actually choose, case by case, instead of reaching for the same default every time.', 'beginner', ARRAY['tomas','imani'], '{"requiredMissionIds":["mission-vec-connected-things-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"connectivity-tradeoffs-sim"}'::jsonb, '{"xp":260,"credits":45}'::jsonb, false, 11),
  ('mission-vec-connected-things-12', 'world-vec-connected-things', 'campaign-vec-connected-things', 'operation-vec-connected-things-2', 'ten-thousand-offline-devices', 'Ten Thousand Offline Devices', 'Most of these controllers were never given a real device identity or a connectivity plan of any kind -- they were installed once, decades ago, and simply left running. Vector Division has to design the plan that should have existed from day one, and prove the count was never an attack.', 'boss', ARRAY['imani','byte','tomas'], '{"requiredMissionIds":["mission-vec-connected-things-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"ten-thousand-offline-boss-sim"}'::jsonb, '{"xp":1100,"credits":230,"badgeIds":["ten-thousand-offline"],"skillXp":{"robotics_fundamentals":140}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-connected-things-01', 1, 'imani', 'The sweep finished overnight. Byte, give me the number.'),
  ('mission-vec-connected-things-01', 2, 'byte', 'Every embedded controller across every facility we have access to, matched against the door''s signature from Act 13 -- population count, ten thousand four hundred seventeen.'),
  ('mission-vec-connected-things-01', 3, 'imani', 'Say that again.'),
  ('mission-vec-connected-things-01', 4, 'byte', 'Ten thousand four hundred seventeen matches. Of those, I can currently reach or be reached by eighty-two. The remaining ten thousand three hundred thirty-five have no route in or out of them that I can find at all.'),
  ('mission-vec-connected-things-01', 5, 'tomas', 'That is not a number an attack produces. An attack spreads outward from something. This looks like something that was already there, all along, and simply never counted.'),
  ('mission-vec-connected-things-01', 6, 'imani', 'Then that is the question in front of us. Not who did this. What is actually out there, and why did Vector Division never see it until Byte went looking on purpose.'),

  ('mission-vec-connected-things-02', 1, 'tomas', 'A device identity is not a network address. An address can change every time a device reconnects. An identity is what proves this is the same device it claims to be, no matter what network it happens to be sitting on.'),
  ('mission-vec-connected-things-02', 2, 'byte', 'I pulled provisioning records for a sample of the newly counted controllers. None of them have anything resembling a real identity -- no unique key, no certificate, nothing beyond a shared hardware model number stamped at the factory.'),
  ('mission-vec-connected-things-02', 3, 'tomas', 'A shared model number tells you what kind of device it is. It tells you nothing about which one. That is the entire problem waiting for us on the other end of ten thousand controllers.'),

  ('mission-vec-connected-things-03', 1, 'tomas', 'Provisioning is the process that turns a blank device into a trusted one -- generate a unique identity, install it securely, register that identity with whatever backend is supposed to recognize it, then and only then let the device join a real network.'),
  ('mission-vec-connected-things-03', 2, 'tomas', 'Skip any one of those steps and the device still runs. It just runs with no way to prove who it is, and no way for anything to safely command it.'),
  ('mission-vec-connected-things-03', 3, 'byte', 'None of the sampled controllers have a provisioning record of any kind. As far as I can tell, most of them were installed, powered on, and never touched again.'),
  ('mission-vec-connected-things-03', 4, 'tomas', 'That matches decades-old practice more than it matches negligence. Provisioning as a discipline barely existed when the oldest of these went into a wall.'),

  ('mission-vec-connected-things-04', 1, 'tomas', 'Wi-Fi gives a device real bandwidth and a normal path to the internet through an access point. It also costs real power -- a radio strong enough to reach an access point across a room draws far more current than most of these controllers were ever built to supply continuously.'),
  ('mission-vec-connected-things-04', 2, 'tomas', 'Two bands matter here. 2.4 gigahertz reaches further and passes through walls better. 5 gigahertz moves more data but gives up range to do it. Neither one is free.'),
  ('mission-vec-connected-things-04', 3, 'byte', 'Several hundred of the newly counted controllers already have a Wi-Fi radio sitting on the board, unused. The radio was never the missing piece. The plan to use it was.'),

  ('mission-vec-connected-things-05', 1, 'tomas', 'Bluetooth Low Energy trades range and throughput for power. A BLE radio can run for months or years on a small battery precisely because it spends most of its time asleep.'),
  ('mission-vec-connected-things-05', 2, 'tomas', 'A BLE device spends most of its life advertising -- broadcasting a short, unaddressed signal announcing that it exists. It only opens a real connection when something specifically asks to talk to it.'),
  ('mission-vec-connected-things-05', 3, 'byte', 'That distinction matters for the count. A controller could be advertising right now, in range of a receiver we simply never built, and I would still call it unreachable.'),

  ('mission-vec-connected-things-06', 1, 'tomas', 'Once a BLE connection opens, the device does not just hand over raw bytes. It exposes a structure -- services, and inside each service, characteristics.'),
  ('mission-vec-connected-things-06', 2, 'tomas', 'A service groups a related set of functionality, like battery status or environmental sensing. A characteristic is a single readable, writable or notifiable value inside that service -- a specific piece of data with its own address, called a UUID.'),
  ('mission-vec-connected-things-06', 3, 'tomas', 'Read the structure correctly and a completely unfamiliar BLE device still tells you what it is capable of, before a single line of code is written against it.'),

  ('mission-vec-connected-things-07', 1, 'tomas', 'MQTT solves a specific problem: many small devices, unreliable links, and a need to report without each one holding open a heavyweight connection to a server.'),
  ('mission-vec-connected-things-07', 2, 'tomas', 'Three roles. A publisher sends a message. A subscriber receives it. A broker sits between them, and neither side ever needs to know the other exists -- only the broker and the topic they agree on.'),
  ('mission-vec-connected-things-07', 3, 'byte', 'That decoupling is the part that matters here. A device can publish into the dark, with no idea whether anything is listening, and still be doing its job correctly.'),

  ('mission-vec-connected-things-08', 1, 'tomas', 'A topic is just a hierarchical string, like site/wing-3/door-19/status. Structure it well and one subscriber can listen to an entire wing with a single wildcard. Structure it badly and nothing scales past a handful of devices.'),
  ('mission-vec-connected-things-08', 2, 'tomas', 'Quality of service is a separate promise. At most once fires a message and forgets it. At least once guarantees delivery but may duplicate it. Exactly once guarantees delivery exactly one time, at the highest cost.'),
  ('mission-vec-connected-things-08', 3, 'tomas', 'Ten thousand devices reporting on the wrong quality of service is not a small mistake. It is either a flood of duplicates or a set of silent gaps, multiplied by ten thousand.'),

  ('mission-vec-connected-things-09', 1, 'byte', 'HTTP is the protocol everyone already knows. A device can make a request, get a response, and the whole web already speaks it.'),
  ('mission-vec-connected-things-09', 2, 'tomas', 'It also assumes an open connection is cheap to make and remake, and that text-based headers do not matter. Neither assumption survives contact with a coin-cell battery reporting once an hour.'),
  ('mission-vec-connected-things-09', 3, 'tomas', 'A device polling an HTTP endpoint every few seconds just to check for new instructions spends most of its power budget asking a question with the same answer as last time.'),

  ('mission-vec-connected-things-10', 1, 'tomas', 'CoAP was built to look familiar -- it borrows HTTP''s verbs, GET, PUT, POST, DELETE -- while actually fitting a constrained device''s budget. It runs over UDP instead of TCP, with a header measured in bytes instead of the dozens HTTP spends on plain text.'),
  ('mission-vec-connected-things-10', 2, 'tomas', 'It gives up some of HTTP''s reliability guarantees to get there, and it adds one thing HTTP does not have built in: observe, a way for a device to say tell me when this changes instead of asking over and over.'),
  ('mission-vec-connected-things-10', 3, 'tomas', 'For a device with barely enough power to transmit at all, that is not a minor optimization. It is the difference between reporting for a week and reporting for a year.'),

  ('mission-vec-connected-things-11', 1, 'tomas', 'None of what we just covered is a ranking. Wi-Fi is not better than BLE. MQTT is not always better than CoAP. Each one is a specific answer to a specific budget -- power, range, bandwidth, and how often the device actually needs to speak.'),
  ('mission-vec-connected-things-11', 2, 'imani', 'So when you design the plan for ten thousand controllers, you are not picking one protocol for all of them.'),
  ('mission-vec-connected-things-11', 3, 'tomas', 'Correct. A battery-powered sensor reporting once an hour wants a low-power radio into a nearby gateway and a lightweight publish over MQTT once it gets there. A powered device near a wall outlet with real bandwidth needs can afford Wi-Fi and never has to think twice about it.'),
  ('mission-vec-connected-things-11', 4, 'tomas', 'Get the match wrong in either direction, and either the battery dies in a month, or the powered device wastes bandwidth it never needed to save.'),

  ('mission-vec-connected-things-12', 1, 'imani', 'We have the vocabulary now. Identity, provisioning, half a dozen ways to actually reach a device. Time to point all of it at the real number: ten thousand three hundred thirty-five controllers with no route in or out.'),
  ('mission-vec-connected-things-12', 2, 'tomas', 'Before anyone calls this an attack, look at what is actually missing on every one of them. Not a broken connection. No connection was ever built in the first place.'),
  ('mission-vec-connected-things-12', 3, 'byte', 'I cross-referenced installation dates against every provisioning record I could find anywhere in Nexus archives. Coverage: under one percent. These were not disconnected. They were simply never connected to begin with.'),
  ('mission-vec-connected-things-12', 4, 'imani', 'So the count is not evidence of something spreading. It is evidence of how much of this facility, and probably every facility we operate, was quietly built exactly like that door -- installed once, decades ago, and left running with no identity and no plan.'),
  ('mission-vec-connected-things-12', 5, 'tomas', 'Which means the fix is not incident response. It is the plan that should have existed from day one: real identity for every device, a connectivity approach that actually matches what each one can afford, and a reason to believe the next ten thousand will not end up here too.'),
  ('mission-vec-connected-things-12', 6, 'byte', 'Design it. I will hold the count steady while you do.'),
  ('mission-vec-connected-things-12', 7, 'imani', 'One thing before you start. Identity and a radio are not the same as a working pipeline. Reaching one device is not the same as seeing all of them at once. Solve for one controller here. The scale is the next problem.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-connected-things-01-o1', 'mission-vec-connected-things-01', 1, 'Read the sweep results', 'Judge what Byte''s reachable-versus-total numbers actually reveal about the newly counted controllers.'),
  ('mission-vec-connected-things-01-o2', 'mission-vec-connected-things-01', 2, 'Place the gap in an architecture', 'Identify which layer of a typical IoT architecture is missing for devices Byte cannot reach.'),

  ('mission-vec-connected-things-02-o1', 'mission-vec-connected-things-02', 1, 'Define device identity', 'Choose the accurate distinction between a device identity and a network address.'),
  ('mission-vec-connected-things-02-o2', 'mission-vec-connected-things-02', 2, 'Check the newly found controllers', 'Find the evidence proving the newly counted controllers were never given a real per-device identity.'),

  ('mission-vec-connected-things-03-o1', 'mission-vec-connected-things-03', 1, 'Order the provisioning steps', 'Put identity generation, credential install, backend registration and network join in the order provisioning actually runs.'),
  ('mission-vec-connected-things-03-o2', 'mission-vec-connected-things-03', 2, 'Confirm the gap', 'Find the evidence proving the newly found controllers skipped provisioning entirely.'),

  ('mission-vec-connected-things-04-o1', 'mission-vec-connected-things-04', 1, 'Weigh Wi-Fi''s cost', 'Judge why Wi-Fi is often a poor fit for a small, battery-powered, infrequently-reporting device.'),
  ('mission-vec-connected-things-04-o2', 'mission-vec-connected-things-04', 2, 'Match the vocabulary', 'Match each Wi-Fi term to its accurate definition.'),

  ('mission-vec-connected-things-05-o1', 'mission-vec-connected-things-05', 1, 'Weigh BLE against Wi-Fi', 'Judge why BLE trades range and throughput for power compared to Wi-Fi.'),
  ('mission-vec-connected-things-05-o2', 'mission-vec-connected-things-05', 2, 'Tell advertising from connected', 'Choose the accurate distinction between a BLE device that is advertising and one that is connected.'),

  ('mission-vec-connected-things-06-o1', 'mission-vec-connected-things-06', 1, 'Match the GATT vocabulary', 'Match each BLE term -- service, characteristic, UUID, property -- to its accurate definition.'),
  ('mission-vec-connected-things-06-o2', 'mission-vec-connected-things-06', 2, 'Order the hierarchy', 'Order a BLE device''s structure from the device itself down to a single value.'),

  ('mission-vec-connected-things-07-o1', 'mission-vec-connected-things-07', 1, 'Define the roles', 'Match publisher, subscriber and broker to their accurate role in MQTT.'),
  ('mission-vec-connected-things-07-o2', 'mission-vec-connected-things-07', 2, 'Order the message flow', 'Order how a single MQTT message actually travels from publisher to subscriber.'),

  ('mission-vec-connected-things-08-o1', 'mission-vec-connected-things-08', 1, 'Match QoS to its guarantee', 'Match each MQTT quality-of-service level to the delivery guarantee it actually makes.'),
  ('mission-vec-connected-things-08-o2', 'mission-vec-connected-things-08', 2, 'Judge the topic design', 'Choose the topic structure that scales safely to ten thousand devices.'),

  ('mission-vec-connected-things-09-o1', 'mission-vec-connected-things-09', 1, 'Weigh HTTP''s assumptions', 'Judge which of HTTP''s ordinary assumptions is costliest for a constrained, battery-powered device.'),
  ('mission-vec-connected-things-09-o2', 'mission-vec-connected-things-09', 2, 'Price out polling', 'Find the evidence showing what frequent HTTP polling actually costs a small device.'),

  ('mission-vec-connected-things-10-o1', 'mission-vec-connected-things-10', 1, 'Compare CoAP and HTTP', 'Choose the accurate description of how CoAP differs from HTTP under the hood.'),
  ('mission-vec-connected-things-10-o2', 'mission-vec-connected-things-10', 2, 'Match CoAP''s features', 'Match each CoAP feature to its accurate description.'),

  ('mission-vec-connected-things-11-o1', 'mission-vec-connected-things-11', 1, 'Match device to connectivity', 'Match each device scenario to the connectivity approach that actually fits its budget.'),
  ('mission-vec-connected-things-11-o2', 'mission-vec-connected-things-11', 2, 'Explain the reasoning', 'Choose the accurate reasoning for why a bad match fails a device in one direction or the other.'),

  ('mission-vec-connected-things-12-o1', 'mission-vec-connected-things-12', 1, 'Assign a real identity', 'Choose what provisioning should actually generate and install for each newly discovered device.'),
  ('mission-vec-connected-things-12-o2', 'mission-vec-connected-things-12', 2, 'Choose the connectivity approach', 'Choose the connectivity approach that fits a resource-constrained, power-limited device reporting periodically.'),
  ('mission-vec-connected-things-12-o3', 'mission-vec-connected-things-12', 3, 'Explain the count', 'Find the evidence proving the count reflects decades of unmanaged installation, not a coordinated event.'),
  ('mission-vec-connected-things-12-o4', 'mission-vec-connected-things-12', 4, 'State the plan', 'Having assigned identity, chosen connectivity and explained the count, state Vector Division''s actual plan for the newly discovered population.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-connected-things-01-o1-c1', 'mission-vec-connected-things-01-o1', 1, 'investigation', 'Which single piece of evidence is the actual scope of what Byte just reported?', '{"evidence":[{"id":"e1","label":"Sweep summary","detail":"10,417 embedded controllers across every facility Vector Division can query match the door''s known signature."},{"id":"e2","label":"Connectivity audit","detail":"Only 82 of those 10,417 controllers currently have any reachable network path in or out."},{"id":"e3","label":"Install record sample","detail":"A sampled batch of matched controllers carries installation dates spanning three decades, with no identity or provisioning record attached to any of them."}],"question":"Which single piece of evidence is the actual scope of what Byte just reported?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-vec-connected-things-01-o2-c1', 'mission-vec-connected-things-01-o2', 1, 'multiple_choice', 'A typical IoT architecture layers a device/edge tier, a network/gateway tier connecting outward, and a cloud or backend tier receiving data. Byte''s reachable-versus-total numbers show the newly counted controllers have working device/edge hardware but are missing which layer?', '{"question":"A typical IoT architecture layers a device/edge tier, a network/gateway tier connecting outward, and a cloud or backend tier receiving data. Byte''s reachable-versus-total numbers show the newly counted controllers have working device/edge hardware but are missing which layer?","options":[{"id":"a","text":"The device/edge layer -- the hardware itself is missing or nonfunctional"},{"id":"b","text":"The network/gateway layer -- nothing connects them outward to anything at all"},{"id":"c","text":"The cloud/backend layer, since the devices already reach the cloud directly"},{"id":"d","text":"No layer is missing, architecture is not relevant to a hardware count"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-connected-things-02-o1-c1', 'mission-vec-connected-things-02-o1', 1, 'multiple_choice', 'Which best describes what a real device identity provides that a network address does not?', '{"question":"Which best describes what a real device identity provides that a network address does not?","options":[{"id":"a","text":"Faster network throughput"},{"id":"b","text":"A durable, unique proof of which specific device this is, independent of whatever address it happens to hold right now"},{"id":"c","text":"A guarantee the device will never go offline"},{"id":"d","text":"Automatic firmware updates"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-connected-things-02-o2-c1', 'mission-vec-connected-things-02-o2', 1, 'investigation', 'Which evidence shows these controllers were never given a real per-device identity?', '{"evidence":[{"id":"e1","label":"Provisioning audit","detail":"Sampled controllers share a single hardware model number, with no per-unit distinguishing value stored anywhere in memory."},{"id":"e2","label":"Network log","detail":"The 82 reachable controllers report a normal range of dynamic network addresses."},{"id":"e3","label":"Firmware note","detail":"Firmware version is identical across the entire sampled batch."}],"question":"Which evidence shows these controllers were never given a real per-device identity?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-connected-things-03-o1-c1', 'mission-vec-connected-things-03-o1', 1, 'interactive_diagram', 'Order the provisioning steps from first to last.', '{"diagramId":"provisioning-sequence","hotspots":[{"id":"generate","label":"Generate a unique identity","explanation":"A key pair or certificate is generated, unique to this one device."},{"id":"install","label":"Install the credentials","explanation":"The identity is written securely onto the device itself."},{"id":"register","label":"Register with the backend","explanation":"The backend records that this identity is now a recognized, trusted device."},{"id":"join","label":"Join the network","explanation":"Only now does the device connect, presenting an identity the backend already recognizes."}],"task":"Order the provisioning steps from first to last."}'::jsonb, '{"correctOrderIds":["generate","install","register","join"]}'::jsonb),
  ('mission-vec-connected-things-03-o2-c1', 'mission-vec-connected-things-03-o2', 1, 'investigation', 'Which evidence best confirms the newly found controllers skipped provisioning entirely, not just one step of it?', '{"evidence":[{"id":"e1","label":"Provisioning log search","detail":"No provisioning record of any kind exists for any controller in the sampled batch."},{"id":"e2","label":"Install log","detail":"The only record for each controller is an installation date, with no credential or registration step logged afterward."},{"id":"e3","label":"Maintenance note","detail":"A technician replaced a fuse on one controller five years ago."}],"question":"Which evidence best confirms the newly found controllers skipped provisioning entirely, not just one step of it?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-connected-things-04-o1-c1', 'mission-vec-connected-things-04-o1', 1, 'multiple_choice', 'Why is Wi-Fi often a poor fit for a small, battery-powered, infrequently-reporting embedded device, even though it offers plenty of bandwidth?', '{"question":"Why is Wi-Fi often a poor fit for a small, battery-powered, infrequently-reporting embedded device, even though it offers plenty of bandwidth?","options":[{"id":"a","text":"Wi-Fi cannot carry small amounts of data"},{"id":"b","text":"Maintaining or re-establishing a Wi-Fi connection to an access point draws significant power, which is expensive for a device that only needs to report occasionally"},{"id":"c","text":"Wi-Fi cannot reach the internet without a separate gateway"},{"id":"d","text":"Wi-Fi requires a physical wired connection to operate"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-connected-things-04-o2-c1', 'mission-vec-connected-things-04-o2', 1, 'drag_and_drop', 'Match each Wi-Fi term to its accurate definition.', '{"items":[{"id":"i1","text":"SSID"},{"id":"i2","text":"Access point"},{"id":"i3","text":"2.4 gigahertz band"},{"id":"i4","text":"5 gigahertz band"}],"targets":[{"id":"t1","label":"The network name a device connects to"},{"id":"t2","label":"The hardware a device''s radio actually talks to in order to reach a wired network"},{"id":"t3","label":"Longer range, better wall penetration, more crowded"},{"id":"t4","label":"Higher throughput, shorter range, less crowded"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),

  ('mission-vec-connected-things-05-o1-c1', 'mission-vec-connected-things-05-o1', 1, 'multiple_choice', 'Compared to Wi-Fi, why can Bluetooth Low Energy run for months or years on a small battery?', '{"question":"Compared to Wi-Fi, why can Bluetooth Low Energy run for months or years on a small battery?","options":[{"id":"a","text":"BLE transmits more data per second than Wi-Fi"},{"id":"b","text":"BLE trades range and throughput for power, and spends most of its time asleep rather than maintaining an active connection"},{"id":"c","text":"BLE does not use a radio at all"},{"id":"d","text":"BLE batteries are simply larger than Wi-Fi batteries"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-connected-things-05-o2-c1', 'mission-vec-connected-things-05-o2', 1, 'multiple_choice', 'What is the difference between a BLE device that is advertising and one that is connected?', '{"question":"What is the difference between a BLE device that is advertising and one that is connected?","options":[{"id":"a","text":"They are the same state with different names"},{"id":"b","text":"Advertising is a short, unaddressed broadcast announcing the device exists; a connection only opens once something specifically requests to talk to it"},{"id":"c","text":"A device can only advertise after it has already connected"},{"id":"d","text":"Connected devices use no power at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-connected-things-06-o1-c1', 'mission-vec-connected-things-06-o1', 1, 'drag_and_drop', 'Match each BLE term to its accurate definition.', '{"items":[{"id":"i1","text":"Service"},{"id":"i2","text":"Characteristic"},{"id":"i3","text":"UUID"},{"id":"i4","text":"Notify property"}],"targets":[{"id":"t1","label":"A grouping of related functionality, like battery status"},{"id":"t2","label":"A single readable, writable value inside a service"},{"id":"t3","label":"The unique address identifying a specific service or characteristic"},{"id":"t4","label":"A characteristic property that pushes updates to a subscriber without being asked each time"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),
  ('mission-vec-connected-things-06-o2-c1', 'mission-vec-connected-things-06-o2', 1, 'interactive_diagram', 'Order the BLE structure from the device itself down to a single value.', '{"diagramId":"ble-gatt-hierarchy","hotspots":[{"id":"device","label":"BLE device","explanation":"The physical device exposing everything below it."},{"id":"service","label":"Service","explanation":"A grouped set of related functionality on the device."},{"id":"characteristic","label":"Characteristic","explanation":"A single value inside a service."},{"id":"value","label":"Value","explanation":"The actual data a characteristic currently holds."}],"task":"Order the BLE structure from the device itself down to a single value."}'::jsonb, '{"correctOrderIds":["device","service","characteristic","value"]}'::jsonb),

  ('mission-vec-connected-things-07-o1-c1', 'mission-vec-connected-things-07-o1', 1, 'drag_and_drop', 'Match publisher, subscriber and broker to their accurate role in MQTT.', '{"items":[{"id":"i1","text":"Publisher"},{"id":"i2","text":"Subscriber"},{"id":"i3","text":"Broker"}],"targets":[{"id":"t1","label":"Sends a message to a topic, with no idea who if anyone receives it"},{"id":"t2","label":"Receives messages for topics it has expressed interest in"},{"id":"t3","label":"Sits between publishers and subscribers, routing messages by topic"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),
  ('mission-vec-connected-things-07-o2-c1', 'mission-vec-connected-things-07-o2', 1, 'interactive_diagram', 'Order how a single MQTT message actually travels from publisher to subscriber.', '{"diagramId":"mqtt-message-flow","hotspots":[{"id":"publish","label":"Device publishes","explanation":"A publisher sends a message to a specific topic."},{"id":"broker_receive","label":"Broker receives it","explanation":"The broker accepts the message and checks who is subscribed to that topic."},{"id":"broker_forward","label":"Broker forwards it","explanation":"The broker delivers a copy of the message to every current subscriber of that topic."},{"id":"deliver","label":"Subscriber receives it","explanation":"The subscribing device or service gets the message, with no direct connection to the original publisher ever required."}],"task":"Order how a single MQTT message actually travels from publisher to subscriber."}'::jsonb, '{"correctOrderIds":["publish","broker_receive","broker_forward","deliver"]}'::jsonb),

  ('mission-vec-connected-things-08-o1-c1', 'mission-vec-connected-things-08-o1', 1, 'drag_and_drop', 'Match each MQTT quality-of-service level to the delivery guarantee it actually makes.', '{"items":[{"id":"i1","text":"QoS 0"},{"id":"i2","text":"QoS 1"},{"id":"i3","text":"QoS 2"}],"targets":[{"id":"t1","label":"At most once -- the message is sent and forgotten, with no guarantee it arrives"},{"id":"t2","label":"At least once -- delivery is guaranteed, but the same message might arrive more than once"},{"id":"t3","label":"Exactly once -- delivery is guaranteed exactly one time, at the highest coordination cost"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),
  ('mission-vec-connected-things-08-o2-c1', 'mission-vec-connected-things-08-o2', 1, 'multiple_choice', 'Which topic design scales safely to ten thousand devices reporting status?', '{"question":"Which topic design scales safely to ten thousand devices reporting status?","options":[{"id":"a","text":"One single shared topic that every device publishes to and every subscriber reads"},{"id":"b","text":"A hierarchical topic per device, like site/wing/device-id/status, so a subscriber can use a wildcard to follow exactly the slice it cares about"},{"id":"c","text":"A randomly generated topic name for each message, to avoid collisions"},{"id":"d","text":"No topics at all, since MQTT delivers to everyone by default"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-connected-things-09-o1-c1', 'mission-vec-connected-things-09-o1', 1, 'multiple_choice', 'Which of HTTP''s ordinary assumptions is costliest for a small, battery-powered device?', '{"question":"Which of HTTP''s ordinary assumptions is costliest for a small, battery-powered device?","options":[{"id":"a","text":"That every request needs a response"},{"id":"b","text":"That making and remaking a connection, plus sending verbose text-based headers, is cheap -- an assumption that does not survive contact with a coin-cell battery"},{"id":"c","text":"That data must be sent as plain text"},{"id":"d","text":"That the device has a public IP address"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-connected-things-09-o2-c1', 'mission-vec-connected-things-09-o2', 1, 'investigation', 'Which evidence shows what frequent HTTP polling actually costs a small device, compared to reporting only when needed?', '{"evidence":[{"id":"e1","label":"Power log, polling","detail":"A device polling an HTTP endpoint every 5 seconds for new instructions draws power continuously, even when the answer never changes."},{"id":"e2","label":"Power log, event-driven","detail":"A device that only transmits when it actually has something new to report draws power in short bursts, with long idle stretches in between."},{"id":"e3","label":"Firmware note","detail":"Both devices in this comparison run the identical sensor sampling routine."}],"question":"Which evidence shows what frequent HTTP polling actually costs a small device, compared to reporting only when needed?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-connected-things-10-o1-c1', 'mission-vec-connected-things-10-o1', 1, 'multiple_choice', 'How does CoAP differ from HTTP under the hood, even though it borrows HTTP''s verbs?', '{"question":"How does CoAP differ from HTTP under the hood, even though it borrows HTTP''s verbs?","options":[{"id":"a","text":"CoAP is identical to HTTP in every respect except the name"},{"id":"b","text":"CoAP runs over UDP with a compact binary header instead of HTTP''s TCP connection and verbose text headers, trading some reliability guarantees for a much smaller footprint"},{"id":"c","text":"CoAP requires more power than HTTP in every case"},{"id":"d","text":"CoAP cannot use GET, PUT, POST or DELETE at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-connected-things-10-o2-c1', 'mission-vec-connected-things-10-o2', 1, 'drag_and_drop', 'Match each CoAP feature to its accurate description.', '{"items":[{"id":"i1","text":"Runs over UDP"},{"id":"i2","text":"Compact binary header"},{"id":"i3","text":"Observe"},{"id":"i4","text":"Familiar REST-like verbs"}],"targets":[{"id":"t1","label":"Skips the overhead of establishing and maintaining a TCP connection"},{"id":"t2","label":"Costs a fraction of HTTP''s text-based header size per message"},{"id":"t3","label":"Lets a device say tell me when this changes instead of asking repeatedly"},{"id":"t4","label":"Borrows GET, PUT, POST and DELETE so the model still feels like HTTP"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),

  ('mission-vec-connected-things-11-o1-c1', 'mission-vec-connected-things-11-o1', 1, 'drag_and_drop', 'Match each device scenario to the connectivity approach that actually fits its budget.', '{"items":[{"id":"i1","text":"Battery-powered sensor reporting once an hour"},{"id":"i2","text":"Powered device near a wall outlet needing high bandwidth"},{"id":"i3","text":"Tiny, extremely power-constrained device that only needs occasional REST-like requests"},{"id":"i4","text":"Coin-cell device that must run for years with minimal, infrequent updates"}],"targets":[{"id":"t1","label":"BLE or a similar low-power radio into a nearby gateway, publishing lightly over MQTT"},{"id":"t2","label":"Wi-Fi, since the power budget can absorb it and the bandwidth is actually needed"},{"id":"t3","label":"CoAP over a low-power radio, for REST-like semantics at a fraction of HTTP''s cost"},{"id":"t4","label":"BLE advertising alone may be enough, with an occasional connection to hand off data"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),
  ('mission-vec-connected-things-11-o2-c1', 'mission-vec-connected-things-11-o2', 1, 'multiple_choice', 'What actually goes wrong when the connectivity match is picked in the wrong direction?', '{"question":"What actually goes wrong when the connectivity match is picked in the wrong direction?","options":[{"id":"a","text":"Nothing goes wrong, any protocol works equally well anywhere"},{"id":"b","text":"A power-limited device given a high-power option like continuous Wi-Fi polling drains its battery far too fast, while a well-powered device given an overly restrictive low-bandwidth option wastes capability it could safely use"},{"id":"c","text":"The device simply refuses to boot"},{"id":"d","text":"Only battery-powered devices are ever affected by a bad match"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-connected-things-12-o1-c1', 'mission-vec-connected-things-12-o1', 1, 'multiple_choice', 'Designing the plan for the newly discovered devices, what should the provisioning step actually generate and install for each one?', '{"question":"Designing the plan for the newly discovered devices, what should the provisioning step actually generate and install for each one?","options":[{"id":"a","text":"Reuse a single shared identity across the whole batch, for simplicity"},{"id":"b","text":"A unique cryptographic identity -- a key pair or certificate -- generated per device and installed during provisioning, never shared with any other unit"},{"id":"c","text":"Only a network address, since that already grants access"},{"id":"d","text":"Nothing; firmware version is a sufficient identifier"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-connected-things-12-o2-c1', 'mission-vec-connected-things-12-o2', 1, 'multiple_choice', 'Most of the newly discovered devices are small, power-limited controllers that only need to report status periodically, not stream continuously. Which connectivity approach fits that profile?', '{"question":"Most of the newly discovered devices are small, power-limited controllers that only need to report status periodically, not stream continuously. Which connectivity approach fits that profile?","options":[{"id":"a","text":"Continuous HTTP polling over Wi-Fi every few seconds, for maximum freshness"},{"id":"b","text":"A connectivity approach sized to the device''s power budget -- BLE or Wi-Fi depending on the class of hardware -- paired with lightweight, infrequent MQTT publishes rather than a continuously open HTTP polling loop"},{"id":"c","text":"A single permanent open connection with no protocol at all, to avoid overhead entirely"},{"id":"d","text":"No connectivity, since the devices have run fine without it for decades"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-connected-things-12-o3-c1', 'mission-vec-connected-things-12-o3', 1, 'investigation', 'Which evidence best proves the count reflects decades of unmanaged installation rather than a coordinated event of any kind?', '{"evidence":[{"id":"e1","label":"Installation date spread","detail":"Installation dates for the matched controllers span three decades, with no correlation to any known incident timeline."},{"id":"e2","label":"Provisioning coverage","detail":"Fewer than 1 percent of the matched controllers have any provisioning record at all, and the gap is spread evenly across every era sampled, not concentrated around any recent date."},{"id":"e3","label":"Diagnostic format sample","detail":"A subset of controllers respond to the same raw diagnostic query format as the door from the maintenance-bus incident, consistent with a shared manufacturing era, not shared control by anything."}],"question":"Which evidence best proves the count reflects decades of unmanaged installation rather than a coordinated event of any kind?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-vec-connected-things-12-o4-c1', 'mission-vec-connected-things-12-o4', 1, 'boss_encounter', 'Having assigned identity, chosen connectivity and explained the count, state Vector Division''s actual plan for the newly discovered population.', '{"stages":[{"objectiveRef":"mission-vec-connected-things-12-o1","label":"Assign a real identity"},{"objectiveRef":"mission-vec-connected-things-12-o2","label":"Choose the connectivity approach"},{"objectiveRef":"mission-vec-connected-things-12-o3","label":"Explain the count"}],"task":"State the plan in one paragraph: give each newly discovered device a unique cryptographic identity through real provisioning, match its connectivity approach to its actual power budget instead of defaulting to continuous HTTP polling, and state plainly that the count reflects decades of devices installed with no identity or connectivity plan at all -- history, not an attack."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-connected-things-12-o1","mission-vec-connected-things-12-o2","mission-vec-connected-things-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-connected-things-01-o1-c1', 'orientation', 'Compare the total count against how many are actually reachable right now.', 10, 1),
  ('mission-vec-connected-things-01-o1-c1', 'solution', 'e2 -- only 82 of 10,417 are reachable -- is the actual scope of the discovery; the raw count alone does not tell the story.', 20, 2),
  ('mission-vec-connected-things-01-o2-c1', 'orientation', 'Ask which layer actually gets a signal off a device and out to anything else.', 10, 1),
  ('mission-vec-connected-things-01-o2-c1', 'solution', 'The network/gateway layer is missing -- the device/edge hardware works fine, it simply has nothing carrying its signal anywhere.', 20, 2),

  ('mission-vec-connected-things-02-o1-c1', 'orientation', 'An address describes where a device currently is on a network, not which device it actually is.', 10, 1),
  ('mission-vec-connected-things-02-o1-c1', 'solution', 'A real identity is a durable, unique proof of which specific device this is, independent of whatever address it happens to hold right now.', 20, 2),
  ('mission-vec-connected-things-02-o2-c1', 'orientation', 'Look for evidence about what varies -- or does not vary -- between individual units.', 10, 1),
  ('mission-vec-connected-things-02-o2-c1', 'solution', 'e1: the sampled controllers share one model number with no per-unit distinguishing value anywhere -- that is the missing identity.', 20, 2),

  ('mission-vec-connected-things-03-o1-c1', 'orientation', 'Nothing can be installed before it is generated, and nothing can join a network before the backend already recognizes it.', 10, 1),
  ('mission-vec-connected-things-03-o1-c1', 'concept', 'Provisioning is a one-way sequence: an identity has to exist before it can be installed, and it has to be registered before a network join actually means anything.', 20, 2),
  ('mission-vec-connected-things-03-o1-c1', 'solution', 'Generate the identity, install the credentials, register with the backend, then join the network.', 30, 3),
  ('mission-vec-connected-things-03-o2-c1', 'orientation', 'Look for evidence that no provisioning step happened at all, not just a note about hardware.', 10, 1),
  ('mission-vec-connected-things-03-o2-c1', 'solution', 'e1: no provisioning record exists anywhere for the sampled batch -- provisioning was skipped entirely, not just one step of it.', 20, 2),

  ('mission-vec-connected-things-04-o1-c1', 'orientation', 'Ask what it costs a radio to establish and hold a connection to an access point, not just to send data once connected.', 10, 1),
  ('mission-vec-connected-things-04-o1-c1', 'solution', 'Maintaining a Wi-Fi connection draws significant power continuously, which is expensive for a device that only needs to report occasionally.', 20, 2),
  ('mission-vec-connected-things-04-o2-c1', 'orientation', 'Match each term to whether it names the network, the hardware, or a frequency trade-off.', 10, 1),
  ('mission-vec-connected-things-04-o2-c1', 'solution', 'SSID names the network. The access point is the hardware bridging to the wired network. 2.4GHz favors range; 5GHz favors throughput.', 20, 2),

  ('mission-vec-connected-things-05-o1-c1', 'orientation', 'Ask what a radio spends most of its energy doing: transmitting, or simply staying connected.', 10, 1),
  ('mission-vec-connected-things-05-o1-c1', 'solution', 'BLE trades range and throughput for power by spending most of its time asleep rather than holding an active connection open.', 20, 2),
  ('mission-vec-connected-things-05-o2-c1', 'orientation', 'One state broadcasts to no one in particular; the other requires a specific request first.', 10, 1),
  ('mission-vec-connected-things-05-o2-c1', 'solution', 'Advertising is an unaddressed broadcast announcing the device exists; a connection only opens once something specifically requests one.', 20, 2),

  ('mission-vec-connected-things-06-o1-c1', 'orientation', 'Ask which term names a group, which names a single value, which names an address, and which names a behavior.', 10, 1),
  ('mission-vec-connected-things-06-o1-c1', 'solution', 'Service groups functionality. Characteristic is a single value. UUID is the address. Notify pushes updates without being asked each time.', 20, 2),
  ('mission-vec-connected-things-06-o2-c1', 'orientation', 'Nothing can hold a value before it has a characteristic, and nothing can have a characteristic before it has a service.', 10, 1),
  ('mission-vec-connected-things-06-o2-c1', 'solution', 'Device, then service, then characteristic, then the value itself.', 20, 2),

  ('mission-vec-connected-things-07-o1-c1', 'orientation', 'One role sends without knowing who is listening, one role listens without knowing who sent it, and one role sits between them.', 10, 1),
  ('mission-vec-connected-things-07-o1-c1', 'solution', 'Publisher sends into a topic, subscriber receives from a topic, broker routes between them.', 20, 2),
  ('mission-vec-connected-things-07-o2-c1', 'orientation', 'The broker always sits in the middle -- nothing skips it in either direction.', 10, 1),
  ('mission-vec-connected-things-07-o2-c1', 'solution', 'Publish, then the broker receives it, then the broker forwards it, then the subscriber receives it.', 20, 2),

  ('mission-vec-connected-things-08-o1-c1', 'orientation', 'Ask how many times, at minimum and at most, each level actually guarantees delivery.', 10, 1),
  ('mission-vec-connected-things-08-o1-c1', 'concept', 'QoS 0 promises nothing beyond a single send. QoS 1 promises at least one delivery, at the risk of duplicates. QoS 2 promises exactly one delivery, at real coordination cost.', 20, 2),
  ('mission-vec-connected-things-08-o1-c1', 'solution', 'QoS 0: at most once. QoS 1: at least once, possible duplicates. QoS 2: exactly once, highest cost.', 30, 3),
  ('mission-vec-connected-things-08-o2-c1', 'orientation', 'Ask whether the topic design lets a subscriber follow a slice of the fleet, or forces it to listen to everything.', 10, 1),
  ('mission-vec-connected-things-08-o2-c1', 'solution', 'A hierarchical per-device topic with wildcard support scales; one shared topic for every device does not.', 20, 2),

  ('mission-vec-connected-things-09-o1-c1', 'orientation', 'Ask what HTTP assumes is cheap that a coin-cell battery cannot actually afford.', 10, 1),
  ('mission-vec-connected-things-09-o1-c1', 'solution', 'HTTP assumes making and remaking connections plus verbose text headers is cheap -- that assumption is what costs a small battery the most.', 20, 2),
  ('mission-vec-connected-things-09-o2-c1', 'orientation', 'Compare what each device is doing while it has nothing new to say.', 10, 1),
  ('mission-vec-connected-things-09-o2-c1', 'solution', 'e1: polling every 5 seconds draws power continuously even when nothing has changed -- that is the real cost of polling.', 20, 2),

  ('mission-vec-connected-things-10-o1-c1', 'orientation', 'Borrowed verbs are not the same as a borrowed transport or header format.', 10, 1),
  ('mission-vec-connected-things-10-o1-c1', 'solution', 'CoAP runs over UDP with a compact binary header, trading some of TCP and HTTP''s reliability guarantees for a much smaller footprint.', 20, 2),
  ('mission-vec-connected-things-10-o2-c1', 'orientation', 'Match each feature to whether it saves on connection setup, header size, repeated asking, or familiarity.', 10, 1),
  ('mission-vec-connected-things-10-o2-c1', 'solution', 'UDP skips connection setup. Compact header saves bytes per message. Observe replaces repeated asking. Familiar verbs keep the model close to HTTP.', 20, 2),

  ('mission-vec-connected-things-11-o1-c1', 'orientation', 'Match each device profile to how much power and bandwidth it can actually spare.', 10, 1),
  ('mission-vec-connected-things-11-o1-c1', 'concept', 'A tight power budget wants a low-power radio and a lightweight publish pattern; a generous power budget can afford whatever bandwidth it actually needs.', 20, 2),
  ('mission-vec-connected-things-11-o1-c1', 'solution', 'Battery sensor: BLE/gateway plus MQTT. Powered high-bandwidth device: Wi-Fi. Tiny constrained device: CoAP. Coin-cell device: BLE advertising alone may suffice.', 30, 3),
  ('mission-vec-connected-things-11-o2-c1', 'orientation', 'Think about which direction the mismatch runs: too much power spent, or too little capability used.', 10, 1),
  ('mission-vec-connected-things-11-o2-c1', 'solution', 'A power-limited device given a high-power option drains its battery too fast; a well-powered device given an overly restrictive option wastes capability it could safely use.', 20, 2),

  ('mission-vec-connected-things-12-o1-c1', 'orientation', 'Think back to what a real device identity actually requires, and whether it can ever be shared between units.', 10, 1),
  ('mission-vec-connected-things-12-o1-c1', 'solution', 'A unique cryptographic identity generated and installed per device during provisioning, never shared with any other unit.', 20, 2),
  ('mission-vec-connected-things-12-o2-c1', 'orientation', 'Match the connectivity choice to a device that reports occasionally, not one that streams continuously.', 10, 1),
  ('mission-vec-connected-things-12-o2-c1', 'concept', 'Continuous HTTP polling over Wi-Fi is sized for a device that needs constant freshness, not one reporting periodically on a limited power budget.', 20, 2),
  ('mission-vec-connected-things-12-o2-c1', 'solution', 'Size the radio to the device''s power budget -- BLE or Wi-Fi depending on hardware class -- and report with lightweight, infrequent MQTT publishes instead of continuous HTTP polling.', 30, 3),
  ('mission-vec-connected-things-12-o3-c1', 'orientation', 'Look for evidence that the gap is spread evenly across decades, not clustered around any one event.', 10, 1),
  ('mission-vec-connected-things-12-o3-c1', 'solution', 'e2: under 1 percent provisioning coverage, spread evenly across every era sampled, proves this is decades of unmanaged installation, not a coordinated event.', 20, 2),
  ('mission-vec-connected-things-12-o4-c1', 'orientation', 'Combine all three judgments into one plan: identity, connectivity, and the explanation for the count.', 15, 1),
  ('mission-vec-connected-things-12-o4-c1', 'solution', 'Give every device a unique identity through real provisioning, match its connectivity to its actual power budget instead of defaulting to HTTP polling, and state plainly that the count is decades of history, not an attack.', 25, 2);
